pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 reentrantAmount, uint256 attackerSeed) public {
        // Keep amounts in a wide admissible range, avoid overflow in helper.
        vm.assume(depositAmount > 0 && depositAmount < type(uint128).max);
        vm.assume(reentrantAmount > 0 && reentrantAmount < type(uint128).max);
        // Attacker seed just to derive a deterministic address with code; we will deploy a fresh helper.
        address attacker = address(new ReentrantAttacker(address(c)));
        // Fund the attacker and let it deposit.
        vm.deal(attacker, depositAmount + reentrantAmount);
        vm.startPrank(attacker);
        c.addToBalance{value: depositAmount}();
        // Now attacker withdraws, which triggers reentrant addToBalance in its receive.
        // The ReentrantAttacker stores the amount it will re-enter with.
        ReentrantAttacker(payable(attacker)).setReenterAmount(reentrantAmount);
        // Record balance before withdrawal.
        uint256 balBefore = c.getBalance(attacker);
        // The withdrawal sends balBefore ether to attacker, whose receive() will call addToBalance with reentrantAmount.
        c.withdrawBalance();
        vm.stopPrank();
        // After the whole sequence, read userBalance of the attacker.
        uint256 balAfter = c.getBalance(attacker);
        // Invariant: the correct contract's reentrancy lock prevents the reentrant addToBalance from updating
        // storage, so balAfter must be 0 (the withdrawal zeroed the balance).
        // The buggy contract allows the reentrant add, so balAfter > 0.
        assertTrue(balAfter == 0);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public reenterAmount;
    constructor(address _target) payable { target = C(payable(_target)); }
    function setReenterAmount(uint256 _amount) external { reenterAmount = _amount; }
    receive() external payable {
        // Reentrant call: addToBalance with the prepared amount.
        // This only succeeds in the buggy version (no lock).
        target.addToBalance{value: reenterAmount}();
    }
}

