pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 attackerDepositAmount, uint256 reenterAmount) public {
        // Bound values to avoid overflow in add_uint256 or balance mismatch due to arithmetic
        vm.assume(depositAmount > 0 && attackerDepositAmount > 0 && reenterAmount > 0);
        vm.assume(depositAmount + attackerDepositAmount < type(uint256).max);
        vm.assume(reenterAmount <= attackerDepositAmount);

        // Adversarial reentrant attacker that calls addToBalance during withdrawBalance
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // Fund C and the attacker for the reentrancy scenario
        vm.deal(address(c), depositAmount + attackerDepositAmount);
        vm.deal(address(attacker), attackerDepositAmount);

        // Initial deposits
        vm.prank(address(attacker));
        c.addToBalance{value: attackerDepositAmount}();

        // Record pre-attack balance of attacker
        uint256 preBalance = c.getBalance(address(attacker));

        // The attacker triggers withdrawBalance, which reenters into addToBalance with reenterAmount
        attacker.attack(reenterAmount);

        // After the call completes, the property: the attacker's userBalance
        // In the reference, the lock prevents the reentrant addToBalance from updating balances,
        // so final balance should be 0 (withdrew original balance).
        // In the buggy contract, the reentrant addToBalance succeeds, increasing final balance.
        uint256 postBalance = c.getBalance(address(attacker));

        // Universal rule: after a withdrawal, the balance cannot be greater than what could be added
        // if the lock is bypassed. Specifically, the balance after attack must be 0 if lock held.
        assertTrue(postBalance == 0);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 private attackAmount;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 amount) external {
        attackAmount = amount;
        target.withdrawBalance();
    }

    receive() external payable {
        // Reentrant call into addToBalance during withdrawBalance's execution
        if (attackAmount > 0) {
            uint256 amt = attackAmount;
            attackAmount = 0;
            target.addToBalance{value: amt}();
        }
    }
}

