pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialDeposit, uint256 reentrantDeposit) public {
        // keep deposits in practical range to prevent overflow
        bound(initialDeposit, 0, type(uint256).max / 2);
        bound(reentrantDeposit, 0, type(uint256).max / 2);

        // Deploy reentrant attacker that triggers addToBalance during withdraw
        ReentrantAttacker attacker = new ReentrantAttacker(address(c), reentrantDeposit);

        // Fund attacker with initialDeposit + reentrantDeposit (for two separate calls)
        vm.deal(address(attacker), initialDeposit + reentrantDeposit);

        // 1. Attacker makes initial deposit via addToBalance
        vm.prank(address(attacker));
        c.addToBalance{value: initialDeposit}();
        uint256 balanceBefore = c.getBalance(address(attacker));

        // 2. Attacker triggers withdraw, which reenters addToBalance with reentrantDeposit
        vm.prank(address(attacker));
        attacker.attack();
        uint256 balanceAfter = c.getBalance(address(attacker));

        // Invariant: the final balance must not exceed initial balance + reentrantDeposit
        // In correct C, reentrant addToBalance is blocked by nonReentrant_ lock, so balanceAfter == 0
        // In buggy M, reentrant addToBalance succeeds, so balanceAfter > initialDeposit + reentrantDeposit
        assertTrue(balanceAfter <= balanceBefore + reentrantDeposit);
    }
}

