pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 attackAmount) public {
        // Restrict attack amount to avoid overflow in addition and ensure msg.value is non-zero
        vm.assume(attackAmount > 0 && attackAmount < type(uint256).max / 2);

        // Deploy a reentrant attacker that calls addToBalance again during withdrawBalance
        Reenterer reenterer = new Reenterer(c);

        // Fund the attacker and make it deposit something
        vm.deal(address(reenterer), attackAmount * 2);
        vm.prank(address(reenterer));
        c.addToBalance{value: attackAmount}();

        // Record balance after initial deposit
        uint256 balanceBefore = c.getBalance(address(reenterer));

        // Trigger withdrawBalance; the attacker will reenter addToBalance inside its receive
        vm.prank(address(reenterer));
        c.withdrawBalance();

        // After the call, observe the final userBalance of the attacker
        uint256 finalBalance = c.getBalance(address(reenterer));

        // In the reference contract (with lock), the reentrant addToBalance is blocked, so after withdrawBalance
        // the userBalance must be 0 (the cleanup `userBalance[msg.sender] = 0` runs). In the mutant (no lock),
        // the reentrant add succeeds, leaving a non-zero final balance.
        assertTrue(finalBalance == 0);
    }
}

contract Reenterer {
    C public target;
    bool private entered;

    constructor(C _target) {
        target = _target;
        entered = false;
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            // Reenter addToBalance with the received ether
            target.addToBalance{value: msg.value}();
            entered = false;
        }
    }
}

