pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 reentrantAmount) public {
        // keep amounts in a reasonable range to avoid overflow revert in add_uint256
        depositAmount = bound(depositAmount, 0, type(uint128).max);
        reentrantAmount = bound(reentrantAmount, 0, type(uint128).max);
        vm.assume(depositAmount + reentrantAmount < type(uint256).max);

        // deploy the adversarial re-entrant attacker that calls addToBalance in its receive
        Attacker attacker = new Attacker(c);

        // fund the attacker with depositAmount so it can deposit
        vm.deal(address(attacker), depositAmount);

        // let the attacker deposit to acquire some balance
        vm.prank(address(attacker));
        c.addToBalance{value: depositAmount}();

        // set up re-entrant attack: attacker withdraws and in its receive adds reentrantAmount
        attacker.setReentrantAmount(reentrantAmount);
        vm.deal(address(attacker), reentrantAmount);

        // trigger the withdrawal re-entrancy
        vm.prank(address(attacker));
        c.withdrawBalance();

        // After the sequence, the attacker's balance must be 0 in the reference.
        // In the buggy version the re-entrant addToBalance can mutate it, making it non-zero.
        uint256 finalBalance = c.getBalance(address(attacker));
        assertTrue(finalBalance == 0);
    }
}

contract Attacker {
    C target;
    uint256 reentrantAmount;
    bool inFallback;

    constructor(C _target) {
        target = _target;
    }

    function setReentrantAmount(uint256 _amount) external {
        reentrantAmount = _amount;
    }

    receive() external payable {
        // prevent infinite recursion: only re-enter once
        if (!inFallback) {
            inFallback = true;
            target.addToBalance{value: reentrantAmount}();
            inFallback = false;
        }
    }
}

