pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound the amount to a reasonable range to avoid overflow in helpers
        bound(amount, 0, 1e36);
        // Deploy a reentrant attacker that calls addToBalance again
        Attacker attacker = new Attacker();
        // Fund the attacker with the amount to send
        vm.deal(address(attacker), amount);
        // Record state before the call
        uint256 preBalance = address(c).balance;
        uint256 preUserBalance = c.getBalance(address(attacker));
        // Attack: attacker.addToBalance calls c.addToBalance which calls back into attacker.receive() that calls c.addToBalance again
        attacker.attack{value: amount}(address(c));
        // After the attack, the invariant should hold: contract balance == sum of all user balances
        // But only this attacker has balance, so it simplifies to contract balance == attacker's user balance
