contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Admissible domain: depositAmount > 0, withdrawAmount <= depositAmount to avoid revert due to insufficient balance
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount > 0);
        vm.assume(withdrawAmount <= depositAmount);

        // Use a single caller distinct from the test contract
        address caller = makeAddr("caller");
        vm.deal(caller, depositAmount * 2); // enough for deposit + gas

        // Deposit first to establish a balance
        vm.prank(caller);
        c.addToBalance{value: depositAmount}();
        uint256 callerPrevBalance = c.getBalance(caller);

        uint256 contractBalanceBefore = address(c).balance;

        // Perform withdrawal with the chosen amount (withdrawAmount)
        // To test the property, we need a withdrawal that uses the caller's full balance.
        // The withdrawBalance function always withdraws the FULL caller balance, so we must reset to a known state.
        // We redeploy c for a fresh state with the caller having exactly withdrawAmount.
        // Actually, to avoid redeploy overhead and keep it simple, we make a single deposit and full withdrawal.
        // The property holds for any positive deposit held by caller.
        // Since withdrawBalance always withdraws the full balance, we just check the property after withdrawBalance.
        // But we fuzz withdrawAmount to test the invariant on the amount the caller had.
        // Let's set up so caller has exactly withdrawAmount before the withdraw.
        // We can't change the balance except through deposit, so let's do:
        // 1. Deposit depositAmount
        // 2. For a fuzzed withdrawAmount, we need caller's balance to be withdrawAmount before withdrawal.
        // We can achieve that by letting the caller first withdraw his full depositAmount, then deposit withdrawAmount.
        // But withdrawBalance clears balance. So we do:
        // - Deposit depositAmount
        // - Withdraw all (balance becomes 0)
        // - Deposit withdrawAmount (now balance == withdrawAmount)
        // Then test withdrawal of that amount.
        // However, the deposit might be from original caller, just reuse.

        // First withdrawal of depositAmount
        vm.prank(caller);
        c.withdrawBalance();

        // Now deposit exactly withdrawAmount
        vm.prank(caller);
        c.addToBalance{value: withdrawAmount}();
        uint256 balanceBefore = c.getBalance(caller);
        uint256 contractBalanceBeforeWithdraw = address(c).balance;

        // Perform the withdrawal
        vm.prank(caller);
        try c.withdrawBalance() {} catch {}

        // Property: Contract balance decreased by exactly balanceBefore
        assertTrue(address(c).balance == contractBalanceBeforeWithdraw - balanceBefore);
    }
}

